window.RP_SESSION={"id":"S-98590e34c77c","messages":[{"id":"RP-III-0084314","time":"2026-04-25T20:22:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"낮의 열기가 식은 훈련장. 션이 원형 방패를 빙글빙글 돌리면서 거의 다 빨아들인 궐련을 바닥에 투 뱉었다. 그러고는 자기 팔 길이만한 아밍소드를 본 뜬 목검을 집어들었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0084315","time":"2026-04-25T20:24:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"마리, 준비됐니?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0084316","time":"2026-04-25T20:25:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"내 부상이 벌써 나았던가. 언제부터 나았던거지. 마리우스 역시도 목검을 잡아들고는 멈칫거렸다. 아직까지 오른발이 저린데 나는 왜 검을 들고 있는가···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0084317","time":"2026-04-25T20:26:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 준비가 되어있어야, 겠··· 죠? ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0084318","time":"2026-04-25T20:32:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"음, 다리가 불편한 김에 무게중심을 옮기는 걸 연습해보자.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0084319","time":"2026-04-25T20:34:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 왼쪽으로 중심을 둬보는 거요? ”\n\n마리우스는 곰곰히 시도해보려는 듯, 슬쩍 몸을 낮추며 왼쪽으로 조금 더 숙여보았다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0084320","time":"2026-04-25T20:34:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"어정쩡한 느낌···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0084321","time":"2026-04-25T20:36:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"아니, 자유자재로 검을 맞댈 때마다 힘을 빼고 치는 거지.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0084322","time":"2026-04-25T20:37:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 힘을 빼고요? 그러니까, 이걸···. “","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0084323","time":"2026-04-25T20:38:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"힘을 빼내고, 친다고? 으응? 온 머리에 물음표 띄우고서는 가만히 흙바닥을 바라본다. 생각하거나 고민할 때 있는 습관.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0084324","time":"2026-04-25T21:00:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"딱!\n\n\"집중해!\"\n\n션이 가만히 있는 틈에 방패를 밀어 올리며 마리우스의 목검과 팔을 쳐냈다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0084325","time":"2026-04-26T00:18:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0084326","time":"2026-04-26T00:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
